head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF95000";
scwin.inst_passyn = null;
scwin.mod_del_cd = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — result

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.inst_passyn = '' + dma_pageContext.get("instPassyn") + '';
        scwin.mod_del_cd = '' + dma_pageContext.get("modDelCd") + '';
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf95000.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_otherwise_9", fn: function(){ return (!((!(String(((dma_pageContext.get("result") ?? "")) == null ? '' : ((dma_pageContext.get("result") ?? ""))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $c.util.getComponent("ipt_passWord").focus();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf95000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_sendForm_onclick
 * @description btn_sendForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sendForm_onclick = async function(e){
    try {
        await scwin.sendForm()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf95000.btn_sendForm_onclick' }); }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf95000.btn_self_onclick' }); }
};

/**
 * @method
 * @name __on_enter_1_ipt_password
 * @description on enter 1 ipt password 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_1_ipt_password = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.sendForm() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf95000.__on_enter_1_ipt_passWord' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_sendForm
 * @description send Form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_sendForm = async function () {
    const sbmOptions = {
        id: "tx_sendForm",
        method: "post",
        action: "/common/password.do?method=passwordCheck",
        ref: "dma_sendFormReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name sendForm
 * @description send Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sendForm = async function () {
    let passWord = $c.util.getComponent('ipt_passWord').getValue(); if (passWord == null) { passWord = ''; }
    if (passWord === "") {
        await $c.win.alert("패스워드를 입력하세요.");
        return;
    }
    const key = CryptoJS.enc.Hex.parse('000102030405060708090a0b0c0d0e0f');
    const iv = CryptoJS.enc.Hex.parse('101112131415161718191a1b1c1d1e1f');
    const message = $c.util.getComponent('ipt_passWord').getValue();
    const padMsg = padString(message);
    const encrypted = CryptoJS.AES.encrypt(padMsg, key, { iv: iv, padding: CryptoJS.pad.NoPadding, mode: CryptoJS.mode.CBC });
    $c.util.getComponent('dma_sendFormReq').set('passWordTest', encrypted);
    await scwin.tx_sendForm();
};
